    const states=document.querySelectorAll('.signal em'); const descriptions=document.querySelectorAll('.signal span'); if(states[3])states[3].textContent='real'; if(states[4])states[4].textContent='triagem'; if(descriptions[3])descriptions[3].textContent='snapshot comunitário com contagem de avatares por região.'; if(descriptions[4])descriptions[4].textContent='offline é um sinal de revisão, nunca confirmação de abandono.';
    const stage=$('mapStage');const mapCanvas=$('mapCanvas');if(!stage||!mapCanvas)return;const xs=busy.map((item)=>Number(item.x||0));const ys=busy.map((item)=>Number(item.y||0));const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);stage.innerHTML=busy.length?busy.slice(0,10).map((item,index)=>{const left=12+((Number(item.x||0)-minX)/Math.max(maxX-minX,1))*76;const top=15+((Number(item.y||0)-minY)/Math.max(maxY-minY,1))*66;return '<button class="map-marker" style="left:'+left+'%;top:'+top+'" title="'+escapeHtml(item.name)+'" data-name="'+escapeHtml(item.name)+'" data-avatars="'+Number(item.avatars||0)+'"><span>'+escapeHtml(item.name)+'</span></button>'}).join(''):'<div class="map-empty">snapshot indisponível</div>';stage.querySelectorAll('.map-marker').forEach((marker)=>marker.addEventListener('click',(event)=>{event.stopPropagation();openRegion(marker.dataset.name,Number(marker.dataset.avatars),regionUrl(marker.dataset.name));}));$('mapFeedMeta').textContent=busy.length+' regiões · scan '+scanTime;$('mapStatus').textContent=busy.length+' marcadores públicos · arraste ou use o zoom';applyMapTransform();
