  const intelligenceState={directoryPage:1,landPage:1};
  async function jsonResponse(url){const response=await fetch(url,{cache:'no-store'});const data=await response.json();if(!response.ok||data.status==='unavailable'){const error=new Error(data.error||data.message||'fonte indisponível');error.payload=data;error.status=response.status;throw error;}return data;}
  function renderStats(data){const home=data.home||{};const stats=data.stats||{};const totals=home.totals||stats;$('statRegions').textContent=number(totals.regions);$('statAvatars').textContent=number(totals.avatars);$('statCrowded').textContent=number(totals.regions_with_people);$('statForSale').textContent=number(totals.for_sale);const scan=home.latest_scan||home.scan; $('statsUpdated').textContent=scan&&scan.generated_at?'scan '+new Date(scan.generated_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'snapshot público';const changes=(stats.recent_changes||[]).slice(0,8);const chart=$('statsChart');if(!changes.length){chart.innerHTML='<strong>Atividade recente</strong><p>sem mudanças reportadas no último snapshot.</p>';return;}const offline=changes.filter((item)=>item.rating_slug==='offline'||item.event==='offline').length;const rating=changes.filter((item)=>item.event==='rating_changed').length;const lastY=18+((changes.length%4)*4);chart.innerHTML='<strong>Atividade recente</strong><p>'+number(changes.length)+' mudanças observadas · '+number(offline)+' offline em revisão · '+number(rating)+' mudanças de classificação</p><svg viewBox="0 0 420 82" preserveAspectRatio="none" aria-label="Resumo de mudanças"><polyline points="8,68 66,'+(68-(offline*8))+' 124,'+(68-(rating*7))+' 182,34 240,48 298,26 356,40 412,'+lastY+'" fill="none" stroke="#8bf0cf" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><line x1="8" y1="68" x2="412" y2="68" stroke="rgba(198,237,224,.18)"/></svg>'}
  function renderLanguages(data){const items=(data.languages||[]).slice(0,8);const max=Math.max(...items.map((item)=>Number(item.regions||0)),1);$('languageList').innerHTML=items.length?'<div class="source-note-inline" style="margin-bottom:5px">idioma provável · descrição tem mais confiança que nome</div>'+items.map((item)=>'<div class="language-item"><span class="language-name">'+escapeHtml(item.name||item.code)+'</span><span class="language-track"><i style="width:'+Math.max(4,(Number(item.regions||0)/max)*100)+'%"></i></span><span class="language-count">'+number(item.regions)+' regiões</span></div>').join(''):'<div class="row"><div><strong>Idiomas indisponíveis</strong><p>o conector não respondeu.</p></div></div>';}
  function renderDirectory(data){const items=data.items||[];$('directoryMeta').textContent=number(data.total||0)+' resultados · página '+number(data.page||1)+'/'+number(data.pages||1);$('directoryPage').textContent='página '+number(data.page||1)+' de '+number(data.pages||1);$('directoryPrev').disabled=Number(data.page||1)<=1;$('directoryNext').disabled=Number(data.page||1)>=Number(data.pages||1);$('directoryList').innerHTML=items.length?items.map((item)=>'<div class="row"><div><strong>'+escapeHtml(item.name||item.region)+'</strong><p>'+escapeHtml(item.type==='parcel'?'parcela · ':'região · ')+(item.region&&item.name!==item.region?escapeHtml(item.region)+' · ':'')+escapeHtml(item.rating||'')+' · '+number(item.avatars)+' av. · '+(item.online?'online':'offline')+(item.for_sale?' · à venda':'')+'</p></div><button class="section-link region-open" data-region="'+escapeHtml(item.region||item.name)+'">analisar ↗</button></div>').join(''):'<div class="row"><div><strong>Nenhum resultado</strong><p>Tente outro termo, idioma ou classificação.</p></div></div>';document.querySelectorAll('.region-open').forEach((button)=>button.addEventListener('click',()=>openRegionDetail(button.dataset.region)));}
  async function loadDirectory(){const params=new URLSearchParams();const q=$('directorySearch').value.trim();const rating=$('directoryRating').value;const lang=$('directoryLanguage').value;if(q)params.set('q',q);if(rating)params.set('rating',rating);if(lang)params.set('lang',lang);params.set('page',String(intelligenceState.directoryPage));try{renderDirectory(await jsonResponse('/api/intelligence/search?'+params.toString()));}catch(error){$('directoryList').innerHTML='<div class="row"><div><strong>Diretório indisponível</strong><p>'+escapeHtml(error.message)+'</p></div><span class="badge muted">sem leitura</span></div>';}}
