  function renderRegionHistory(history){const svg=$('detailHistory');const items=(history||[]).slice(-24);if(items.length<2){svg.innerHTML='<text x="14" y="48" fill="#627773" font-size="10">histórico insuficiente para esta região</text>';return;}const values=items.map((item)=>Number(item.avatars||0));const min=Math.min(...values);const max=Math.max(...values);const span=Math.max(max-min,1);const points=values.map((value,index)=>((index/(values.length-1))*408+6).toFixed(1)+','+(82-((value-min)/span)*62).toFixed(1)).join(' ');svg.innerHTML='<polyline points="'+points+'" fill="none" stroke="#8bf0cf" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><line x1="6" y1="82" x2="414" y2="82" stroke="rgba(198,237,224,.18)"/><text x="8" y="14" fill="#94aaa5" font-size="9">'+number(max)+'</text><text x="8" y="91" fill="#627773" font-size="9">'+number(min)+'</text>';}
  async function openRegionDetail(name){if(!name)return;const panel=$('regionDetail');panel.hidden=false;$('detailName').textContent='Carregando '+name+'…';$('detailSummary').textContent='consultando histórico, idioma e parcelas públicas';panel.scrollIntoView({behavior:'smooth',block:'center'});try{const data=await jsonResponse('/api/intelligence/region?name='+encodeURIComponent(name));$('detailName').textContent=data.name||name;const lang=data.language&&data.language.name?data.language.name:'idioma não estimado';$('detailSummary').textContent=(data.rating||'classificação não informada')+' · '+number(data.avatars)+' avatares · '+(data.online?'online':'offline em revisão')+' · '+lang+' · coordenadas '+number(data.x)+', '+number(data.y);$('detailChips').innerHTML='<span class="chip">'+number((data.for_sale||[]).length)+' à venda</span><span class="chip">'+number((data.all_parcels||[]).length)+' parcelas mapeadas</span><span class="chip">'+(data.history&&data.history.length?number(data.history.length)+' leituras':'sem histórico')+'</span>';const slurl=data.slurl||regionUrl(data.name);$('detailSlurl').href=slurl;$('detailViewer').href=data.viewer_link||'secondlife:///app/teleport/'+encodeURIComponent(data.name)+'/128/128/25';$('detailImage').src=data.map_image||'https://map.secondlife.com/map-3-1000-1000-objects.jpg';$('detailImage').alt='Mapa de '+data.name;renderRegionHistory(data.history);$('detailSource').textContent='fonte: Inworld Map · scan '+(data.history&&data.history.length?new Date(data.history[data.history.length-1].when).toLocaleString('pt-BR'):'sem timestamp');}catch(error){$('detailSummary').textContent='Não foi possível carregar os detalhes desta região agora.';$('detailChips').innerHTML='<span class="chip">fonte indisponível</span>';}}
  async function loadIntelligence(){ensureIntelLab();try{const data=await Promise.all([jsonResponse('/api/intelligence/home'),jsonResponse('/api/intelligence/stats'),jsonResponse('/api/intelligence/languages')]);renderStats({home:data[0],stats:data[1]});renderLanguages(data[2]);renderIntelLab(data[1]);}catch(error){$('statsUpdated').textContent='fonte indisponível';renderIntelLab({});}await Promise.all([loadDirectory(),loadLand()]);}
