  let intelligenceStats={};
  function ensureIntelLab(){if($('intel-lab'))return;const section=document.createElement('section');section.id='intel-lab';section.className='section intel-lab view-section';section.dataset.view='intelligence';section.innerHTML='<div class="section-head"><div><div class="showbuzz-kicker"><i></i> leitura analítica</div><h2>Atividade, composição e comparação</h2><p>Transforme o snapshot público em contexto: tendência, maturidade, mudanças e duas regiões lado a lado.</p></div><span class="source-note" id="intelLabUpdated">aguardando snapshot</span></div><div class="intel-lab-grid"><div class="panel intel-panel"><div class="panel-head"><h3>Atividade do grid</h3><div class="intel-panel-controls"><select id="activityMetric" aria-label="Métrica da atividade"><option value="avatars">avatares</option><option value="regions">regiões</option><option value="parcels_for_sale">lotes à venda</option></select><select id="activityRange" aria-label="Período da atividade"><option value="14">14 leituras</option><option value="30">30 leituras</option><option value="60">todas</option></select></div></div><div class="intel-summary"><span id="activitySummary">sem histórico disponível</span><strong id="activityDelta">—</strong></div><div class="activity-chart" id="activityChart"><div class="compare-empty">carregando histórico de scans…</div></div><div class="intel-note">Fonte: Inworld Map · série por scan público, sem identificação de avatares.</div></div><div class="panel intel-panel"><div class="panel-head"><h3>Composição por maturidade</h3><small id="ratingMixMeta">snapshot público</small></div><div class="rating-mix" id="ratingMix"><div class="compare-empty">carregando distribuição…</div></div><div class="intel-note">A classificação descreve a região no snapshot; não é avaliação de qualidade ou segurança.</div></div></div><div class="panel intel-panel changes-panel"><div class="panel-head"><h3>Watchlist de mudanças</h3><div class="intel-panel-controls"><select id="intelChangeFilter" aria-label="Filtrar mudanças"><option value="all">todas</option><option value="rating_changed">classificação alterada</option><option value="offline">offline em revisão</option><option value="new">novas regiões</option></select><small id="intelChangeMeta">aguardando</small></div></div><div class="intel-changes" id="intelChangeList"><div class="compare-empty">carregando sinais…</div></div></div><div class="panel intel-panel compare-panel"><div class="panel-head"><h3>Comparar regiões</h3><small>crowd, rating, idioma e histórico</small></div><div class="compare-form"><input id="compareRegionA" placeholder="Primeira região" aria-label="Primeira região"><input id="compareRegionB" placeholder="Segunda região" aria-label="Segunda região"><button class="button primary" id="compareRegions" type="button">Comparar</button></div><div class="compare-result" id="compareResult"><div class="compare-empty">Escolha duas regiões do diretório ou do mapa e compare os snapshots lado a lado.</div></div></div></section>';const intelligenceSection=$('intelligence');if(intelligenceSection)intelligenceSection.after(section);else document.querySelector('main')?.appendChild(section);section.hidden=document.body.dataset.view!=='intelligence';$('activityMetric').addEventListener('change',()=>renderActivityChart(intelligenceStats));$('activityRange').addEventListener('change',()=>renderActivityChart(intelligenceStats));$('intelChangeFilter').addEventListener('change',()=>renderIntelChanges(intelligenceStats));$('compareRegions').addEventListener('click',loadRegionCompare);}
  function renderActivityChart(stats){const items=(stats.by_scan||[]).filter((item)=>item&&item.when).slice(-(Number($('activityRange')?.value||14)||14));const metric=$('activityMetric')?.value||'avatars';const labels={avatars:'avatares',regions:'regiões',parcels_for_sale:'lotes à venda'};if(!items.length){$('activityChart').innerHTML='<div class="compare-empty">A fonte não trouxe histórico suficiente.</div>';$('activitySummary').textContent='sem histórico disponível';$('activityDelta').textContent='—';return;}const values=items.map((item)=>Number(item[metric]||0));const min=Math.min(...values);const max=Math.max(...values);const span=Math.max(max-min,1);const points=values.map((value,index)=>{const x=10+(index/Math.max(values.length-1,1))*620;const y=184-((value-min)/span)*142;return x.toFixed(1)+','+y.toFixed(1)}).join(' ');const area='10,184 '+points+' 630,184';const first=values[0];const last=values[values.length-1];const delta=first?((last-first)/first)*100:0;$('activitySummary').textContent=labels[metric]+' · '+items.length+' scans · '+number(last)+' no último';$('activityDelta').textContent=(delta>=0?'+':'')+delta.toFixed(1)+'% no período';$('activityChart').innerHTML='<svg viewBox="0 0 640 205" preserveAspectRatio="none" aria-label="Tendência de '+labels[metric]+'"><polygon points="'+area+'" fill="rgba(98,230,210,.12)"></polygon><polyline points="'+points+'" fill="none" stroke="#62e6d2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"></polyline><line x1="10" y1="184" x2="630" y2="184" stroke="rgba(187,202,238,.2)"></line><text x="12" y="18" fill="#b9c9df" font-size="11">'+number(max)+'</text><text x="12" y="201" fill="#71849d" font-size="10">'+number(min)+'</text><text x="565" y="201" fill="#71849d" font-size="10">'+escapeHtml(new Date(items[items.length-1].when).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}))+'</text></svg>';}
