  function compareCard(data,label){const latest=data.history&&data.history.length?data.history[data.history.length-1]:null;const lang=data.language&&data.language.name?data.language.name:'não estimado';return '<article class="compare-card"><h4>'+escapeHtml(label)+' · '+escapeHtml(data.name||'região')+'</h4><p><strong>'+number(data.avatars)+'</strong> avatares · '+(data.online?'online':'offline em revisão')+'</p><p>'+escapeHtml(data.rating||'rating não informado')+' · idioma '+escapeHtml(lang)+'</p><p>coordenadas '+number(data.x)+', '+number(data.y)+' · '+(latest?'última leitura '+number(latest.avatars)+' av.':'sem histórico')+'</p><a href="'+escapeHtml(data.slurl||regionUrl(data.name))+'" target="_blank" rel="noreferrer">abrir SLurl ↗</a></article>';}
