  function eventDateKey(event){return String(event.date||'').trim().slice(0,5);}
  function sltDateKey(offset){const now=new Date();const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',month:'2-digit',day:'2-digit',year:'numeric'}).formatToParts(new Date(now.getTime()+offset*86400000));const month=parts.find((part)=>part.type==='month')?.value||'';const day=parts.find((part)=>part.type==='day')?.value||'';return month+'/'+day;}
  function eventMatchesDay(event, filter){const key=eventDateKey(event);if(!filter)return true;if(filter==='today')return key===sltDateKey(0);if(filter==='tomorrow')return key===sltDateKey(1);if(filter==='week'){const keys=Array.from({length:7},(_,index)=>sltDateKey(index));return keys.includes(key);}return true;}
