  async function loadGroups(){const query=$('groupSearch').value.trim();if(!query){$('groupMeta').textContent='Digite um termo para consultar a busca oficial.';$('groupList').innerHTML='<div class="group-empty">Ex.: música, roleplay, arte, Brasil, ajuda ou tecnologia.</div>';return;}$('groupList').innerHTML='<div class="group-empty">Buscando grupos públicos…</div>';const params=new URLSearchParams({q:query,page:String(groupsState.page)});const sort=$('groupSort').value;const maturity=$('groupMaturity').value;if(sort)params.set('sort',sort);if(maturity)params.set('maturity',maturity);try{renderGroupResults(await jsonResponse('/api/groups-search?'+params.toString()));}catch(error){const officialSearch='https://search.secondlife.com/?query_term='+encodeURIComponent(query)+'&search_type=standard&collection_chosen=groups';$('groupMeta').textContent='relay indisponível · fonte oficial disponível';$('groupList').innerHTML='<div class="group-empty">O relay do Hub não conseguiu acessar o índice agora. A consulta continua disponível diretamente na busca oficial.<br><a class="button secondary" href="'+officialSearch+'" target="_blank" rel="noreferrer">abrir resultados oficiais ↗</a></div>';}}
  $('groupSearchForm').addEventListener('submit',(event)=>{event.preventDefault();groupsState.page=1;setView('groups');loadGroups();});$('groupPrev').addEventListener('click',()=>{if(groupsState.page>1){groupsState.page-=1;loadGroups();}});$('groupNext').addEventListener('click',()=>{groupsState.page+=1;loadGroups();});if(navElement&&!navElement.querySelector('[data-scroll="groups"]')){const groupsNav=document.createElement('button');groupsNav.dataset.scroll='groups';groupsNav.textContent='Grupos';navElement.insertBefore(groupsNav,navElement.children[4]||null);groupsNav.addEventListener('click',()=>setView('groups'));}
  function renderProfile(data){const result=$('presenceResult');if(!result)return;const state='perfil público';const cls='presence-state known';const title=data.display_name||data.input||'Avatar';const key=String(data.agent_id||'key não resolvida');const stamp=data.fetched_at?'lido '+new Date(data.fetched_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'sem timestamp';const hasProfile=Boolean(data.agent_id&&data.profile_url);if(data.status==='static_pages'){const staticLinks=(data.profile_url?'<a href="'+escapeHtml(data.profile_url)+'" target="_blank" rel="noreferrer">abrir perfil público ↗</a>':'')+(data.viewer_url?'<a href="'+escapeHtml(data.viewer_url)+'">abrir no viewer ↗</a>':'');result.innerHTML='<span class="'+cls+'">'+state+'</span><h3>'+escapeHtml(title)+'</h3>'+(data.agent_id?'<div class="presence-meta"><span>key · '+escapeHtml(data.agent_id)+'</span><span>consulta pública pronta</span></div>':'')+'<p>'+escapeHtml(data.message||'A consulta pública está pronta.')+'</p><div class="presence-note">'+escapeHtml(data.note||'O GitHub Pages não executa o relay server-side; o link oficial abre os dados atuais publicados pela fonte.')+'</div><div class="profile-links">'+staticLinks+'</div>';return;}if(!hasProfile){result.innerHTML='<span class="'+cls+'">'+state+'</span><h3>'+escapeHtml(title)+'</h3><p>'+escapeHtml(data.message||'Consulta concluída.')+'</p><div class="presence-note">'+escapeHtml(data.note||'A fonte pública pode publicar apenas parte dos dados do perfil.')+'</div>';if(data.profile_url){const profileLink=document.createElement('a');profileLink.href=data.profile_url;profileLink.target='_blank';profileLink.rel='noreferrer';profileLink.textContent='abrir perfil público ↗';result.appendChild(profileLink);}return;}const photo=data.image_url?'<img class="profile-photo" src="'+escapeHtml(data.image_url)+'" alt="Foto de perfil de '+escapeHtml(title)+'" onerror="this.style.display=&quot;none&quot;">':'<div class="profile-photo" aria-label="Foto não publicada"></div>';const picks=Array.isArray(data.picks)?data.picks:[];const picksHtml=picks.length?picks.map((pick)=>'<article class="profile-pick"><strong>'+escapeHtml(pick.title||'Pick sem título')+'</strong><p>'+escapeHtml(pick.description||'Sem descrição publicada.')+'</p>'+(pick.place_url?'<a href="'+escapeHtml(pick.place_url)+'" target="_blank" rel="noreferrer">abrir local ↗</a>':'')+'</article>').join(''):'<div class="profile-muted">Nenhum pick público foi retornado nesta consulta.</div>';const maturity=data.maturity||'não informado';const links='<div class="profile-links"><a href="'+escapeHtml(data.profile_url)+'" target="_blank" rel="noreferrer">perfil web ↗</a><a href="'+escapeHtml(data.viewer_url)+'">abrir no viewer ↗</a></div>';result.innerHTML='<div class="profile-hero">'+photo+'<div><span class="'+cls+'">'+state+'</span><h3>'+escapeHtml(title)+'</h3><div class="profile-username">'+escapeHtml(data.username||'username não publicado')+'</div>'+links+'</div></div><div class="profile-facts"><span class="profile-fact">key · '+escapeHtml(key)+'</span><span class="profile-fact">maturidade · '+escapeHtml(maturity)+'</span><span class="profile-fact">'+escapeHtml(stamp)+'</span></div><div class="profile-block"><h4>Perfil completo</h4><div class="profile-description">'+escapeHtml(data.description||'Nenhuma descrição pública publicada.')+'</div></div><div class="profile-block"><h4>Picks públicos · '+picks.length+'</h4><div class="profile-picks">'+picksHtml+'</div></div><div class="profile-block"><h4>RL e histórico de nomes</h4><div class="profile-muted">Dados RL: não publicados pela fonte consultada.</div><div class="profile-muted">Histórico completo de nomes: não há endpoint público confiável disponível para esta consulta.</div></div><div class="profile-privacy">'+escapeHtml(data.privacy_note||'Somente dados publicados nas fontes públicas são exibidos.')+'</div>';}
  function isProfileKey(value){return /^(?:[0-9a-f]{32}|[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})$/i.test(value);}
  async function lookupProfile(){const input=$('presenceInput').value.trim();const result=$('presenceResult');if(!input){toast('Digite uma UUID/key');return;}if(!isProfileKey(input)){result.innerHTML='<span class="presence-state">UUID/key necessária</span><h3>Use uma UUID/key válida</h3><p>O Perfil aceita somente UUID/key; nomes e URLs não são consultados para evitar resultados ambíguos.</p>';return;}result.innerHTML='<span class="presence-state">consultando</span><h3>Consultando perfil público…</h3><p>Consultando os dados públicos do perfil.</p>';try{const data=await jsonResponse('/api/avatar-profile?q='+encodeURIComponent(input));renderProfile(data);}catch(error){renderProfile(error.payload||{input,message:error.message||'A consulta não respondeu agora.',note:'Tente novamente em alguns segundos.'});}}
  $('presenceButton').addEventListener('click',lookupProfile);$('presenceInput').addEventListener('keydown',(event)=>{if(event.key==='Enter')lookupProfile();});
  function showbuzzTime(value){if(!value)return 'horário não informado';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);return date.toLocaleString('pt-BR',{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Los_Angeles'}).replace('.','')+' SLT';}
  function renderShowbuzz(data){const filter=$('showbuzzFilter')?.value||'';const live=(data.live||[]).filter((item)=>!filter||item.type===filter).slice(0,14);const upcoming=(data.upcoming||[]).slice(0,10);const imageFallback=' onerror="this.onerror=null;this.src=&quot;https://showbuzz.org/logo.jpeg&quot;"';$('showbuzzLiveCount').textContent=number(data.live_count||data.live?.length||0)+' live';$('showbuzzUpdated').textContent=data.fetched_at?'lido '+new Date(data.fetched_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'snapshot ShowBuzz';$('showbuzzLiveList').innerHTML=live.length?live.map((item)=>'<article class="showbuzz-card"><span class="showbuzz-live-badge">LIVE</span><img class="showbuzz-banner" loading="lazy" src="'+escapeHtml(item.image||'https://showbuzz.org/logo.jpeg')+'" alt="Prévia de '+escapeHtml(item.name)+'"'+imageFallback+'><div class="showbuzz-card-body"><span class="showbuzz-type">'+escapeHtml(item.type_label||item.type||'Live act')+'</span><h4>'+escapeHtml(item.name||'Ato ao vivo')+'</h4><p>'+escapeHtml(item.genre||'gênero não informado')+' · '+escapeHtml(item.venue||'venue não informado')+'</p><p class="showbuzz-crowd">'+number(item.crowd)+' pessoas · '+escapeHtml(item.dresscode||'')+'</p><div class="showbuzz-card-foot"><span>'+escapeHtml(item.rating||'')+'</span><a href="'+escapeHtml(item.slurl||'https://showbuzz.org/')+'" target="_blank" rel="noreferrer">teleportar ↗</a></div></div></article>').join(''):'<div class="showbuzz-empty">Nenhum ato corresponde ao filtro agora. Tente Todos os tipos.</div>';$('showbuzzUpcomingList').innerHTML=data.upcoming_loading?'<div class="showbuzz-empty">Carregando agenda em segundo plano…</div>':upcoming.length?upcoming.map((item)=>'<article class="showbuzz-card upcoming"><img class="showbuzz-banner" loading="lazy" src="'+escapeHtml(item.image||'https://showbuzz.org/logo.jpeg')+'" alt="Banner de '+escapeHtml(item.title)+'"'+imageFallback+'><div class="showbuzz-card-body"><span class="showbuzz-type">próxima festa · '+escapeHtml(item.calendar||'ShowBuzz')+'</span><h4>'+escapeHtml(item.title||'Evento sem título')+'</h4><p>'+escapeHtml(showbuzzTime(item.start))+'</p><p>'+escapeHtml(item.location_name||'local publicado no calendário')+'</p><div class="showbuzz-card-foot"><span>'+escapeHtml(item.description_short||'agenda pública')+'</span><a href="'+escapeHtml(item.slurl||item.html_link||'https://showbuzz.org/')+'" target="_blank" rel="noreferrer">ver evento ↗</a></div></div></article>').join(''):'<div class="showbuzz-empty">Nenhuma próxima festa encontrada agora.</div>';}
  async function loadShowbuzzCalendar(){try{const data=await jsonResponse('/api/showbuzz-calendar');showbuzzData.upcoming=data.upcoming||[];showbuzzData.upcoming_loading=false;renderShowbuzz(showbuzzData);}catch(error){showbuzzData.upcoming=[];showbuzzData.upcoming_loading=false;renderShowbuzz(showbuzzData);}}
  async function loadShowbuzzImages(){const names=[...new Set((showbuzzData.live||[]).map((item)=>item.image_key).filter(Boolean))].slice(0,40);if(!names.length)return;try{const data=await jsonResponse('/api/showbuzz-images?names='+encodeURIComponent(names.join('|')));const images=data.images||{};showbuzzData.live.forEach((item)=>{if(images[item.image_key])item.image=images[item.image_key];});renderShowbuzz(showbuzzData);}catch(error){} }
  async function loadShowbuzz(force){if(showbuzzLoaded&&!force){renderShowbuzz(showbuzzData);return;}try{showbuzzData=await jsonResponse('/api/showbuzz');showbuzzData.upcoming_loading=true;showbuzzLoaded=true;renderShowbuzz(showbuzzData);loadShowbuzzCalendar();loadShowbuzzImages();}catch(error){$('showbuzzLiveList').innerHTML='<div class="showbuzz-empty">ShowBuzz não respondeu agora. Use a fonte original para conferir os atos ao vivo.</div>';$('showbuzzUpcomingList').innerHTML='<div class="showbuzz-empty">Agenda ShowBuzz indisponível no momento.</div>';}}
  $('showbuzzFilter').addEventListener('change',()=>renderShowbuzz(showbuzzData));$('refreshShowbuzz').addEventListener('click',()=>{loadShowbuzz(true);toast('Festas atualizadas pelo ShowBuzz');});
  const catalogState={items:[],filtered:[],mode:'destinations',loaded:false,loading:false,error:'',favorites:new Set(),visited:new Set(),collections:[],activeCollection:''};
  const catalogKeys={favorites:'slhub.catalog.favorites.v1',visited:'slhub.catalog.visited.v1',collections:'slhub.catalog.collections.v1'};
  function catalogRead(key,fallback){try{const value=JSON.parse(localStorage.getItem(key)||'null');return value??fallback;}catch(error){return fallback;}}
  function catalogPersist(){localStorage.setItem(catalogKeys.favorites,JSON.stringify([...catalogState.favorites]));localStorage.setItem(catalogKeys.visited,JSON.stringify([...catalogState.visited]));localStorage.setItem(catalogKeys.collections,JSON.stringify(catalogState.collections));}
  function catalogLoadLocal(){const favorites=catalogRead(catalogKeys.favorites,[]);const visited=catalogRead(catalogKeys.visited,[]);const collections=catalogRead(catalogKeys.collections,[]);catalogState.favorites=new Set(Array.isArray(favorites)?favorites:[]);catalogState.visited=new Set(Array.isArray(visited)?visited:[]);catalogState.collections=Array.isArray(collections)?collections.filter((item)=>item&&item.id&&item.name&&Array.isArray(item.itemIds)):[];catalogState.activeCollection=catalogState.collections[0]?.id||'';}
  function catalogTypeLabel(type){return type==='parcel'?'parcela':type==='experience'?'experiência':'região';}
  function catalogAccessLabel(access){return access==='for-sale'?'à venda':access==='public-check'?'confirme acesso':access||'não informado';}
  function catalogStatusClass(item){return item.data_status==='example'?'catalog-example':item.data_status==='snapshot'?'catalog-snapshot':'';}
  function catalogMatches(item){const query=($('catalogSearch')?.value||'').trim().toLowerCase();const type=$('catalogType')?.value||'';const category=$('catalogCategory')?.value||'';const maturity=$('catalogMaturity')?.value||'';const access=$('catalogAccess')?.value||'';const tag=($('catalogTag')?.value||'').trim().toLowerCase();const favoritesOnly=$('catalogFavoritesOnly')?.checked;const visitedOnly=$('catalogVisitedOnly')?.checked;const eventsOnly=$('catalogEventsOnly')?.checked;const haystack=[item.name,item.region,item.description,item.owner,item.group,item.category,...(item.tags||[])].filter(Boolean).join(' ').toLowerCase();return (!query||haystack.includes(query))&&(!type||item.type===type)&&(!category||item.category===category)&&(!maturity||item.maturity===maturity)&&(!access||item.access===access)&&(!tag||(item.tags||[]).some((value)=>String(value).toLowerCase().includes(tag)))&&(!favoritesOnly||catalogState.favorites.has(item.id))&&(!visitedOnly||catalogState.visited.has(item.id))&&(!eventsOnly||(item.related_events||[]).length>0);}
  function catalogCard(item){const image=item.image?'<img loading="lazy" src="'+escapeHtml(item.image)+'" alt="Prévia de '+escapeHtml(item.name)+'" onerror="this.style.display=\'none\'">':'';const status=item.data_status==='example'?'exemplo local':item.data_status==='snapshot'?'snapshot público':'registro';const tags=(item.tags||[]).slice(0,4).map((tag)=>'<span class="catalog-tag">#'+escapeHtml(tag)+'</span>').join('');const owner=[item.owner?('proprietário: '+item.owner):'',item.group?('grupo: '+item.group):''].filter(Boolean).join(' · ')||'proprietário/grupo não publicado';const events=(item.related_events||[]).length?((item.related_events||[]).length+' evento(s) relacionado(s)'):'sem evento relacionado no recorte';const favorite=catalogState.favorites.has(item.id);const visited=catalogState.visited.has(item.id);return '<article class="catalog-card" data-catalog-card="'+escapeHtml(item.id)+'"><div class="catalog-image">'+image+'<span class="catalog-type">'+escapeHtml(catalogTypeLabel(item.type))+'</span></div><div class="catalog-card-body"><div class="catalog-meta"><span class="'+catalogStatusClass(item)+'">'+escapeHtml(status)+'</span><span>'+escapeHtml(item.maturity||'—')+' · '+escapeHtml(catalogAccessLabel(item.access))+'</span></div><h3><button class="section-link" data-catalog-detail="'+escapeHtml(item.id)+'">'+escapeHtml(item.name)+'</button></h3><p>'+escapeHtml(item.description||'Sem descrição publicada.')+'</p><p class="catalog-owner">'+escapeHtml(owner)+'</p><div class="catalog-tags">'+tags+'</div><div class="catalog-related">'+escapeHtml(events)+'</div><div class="catalog-card-actions"><button type="button" data-catalog-favorite="'+escapeHtml(item.id)+'" class="'+(favorite?'saved':'')+'">'+(favorite?'★ favorito':'☆ favorito')+'</button><button type="button" data-catalog-visited="'+escapeHtml(item.id)+'" class="'+(visited?'saved':'')+'">'+(visited?'✓ visitado':'marcar visitado')+'</button><button type="button" data-catalog-add="'+escapeHtml(item.id)+'">+ coleção</button></div><div class="catalog-card-foot"><a href="'+escapeHtml(item.slurl)+'" target="_blank" rel="noreferrer">abrir SLurl ↗</a><span>'+escapeHtml(item.category||'sem categoria')+'</span></div></div></article>';}
  function catalogRenderLocalStats(){const favorites=$('catalogFavoritesCount');const visited=$('catalogVisitedCount');const collections=$('catalogCollectionsCount');if(favorites)favorites.textContent=String(catalogState.favorites.size);if(visited)visited.textContent=String(catalogState.visited.size);if(collections)collections.textContent=String(catalogState.collections.length);}
  function catalogRenderCollectionControls(){const select=$('catalogCollectionSelect');if(!select)return;select.innerHTML='<option value="">selecione uma coleção</option>'+catalogState.collections.map((item)=>'<option value="'+escapeHtml(item.id)+'" '+(item.id===catalogState.activeCollection?'selected':'')+'>'+escapeHtml(item.name)+' ('+item.itemIds.length+')</option>').join('');}
  function catalogRenderCollections(){const list=$('catalogCollectionsList');if(!list)return;catalogRenderCollectionControls();catalogRenderLocalStats();if(!catalogState.collections.length){list.innerHTML='<div class="catalog-empty">Você ainda não criou uma coleção. Dê um nome acima para guardar landmarks neste navegador.</div>';return;}list.innerHTML=catalogState.collections.map((collection)=>{const items=collection.itemIds.map((id)=>catalogState.items.find((item)=>item.id===id)).filter(Boolean);return '<article class="catalog-collection-card"><h3>'+escapeHtml(collection.name)+'</h3><p>'+items.length+' destino(s) guardado(s) localmente.</p><div class="catalog-tags">'+items.slice(0,5).map((item)=>'<span class="catalog-tag">'+escapeHtml(item.name)+'</span>').join('')+'</div><button type="button" data-catalog-open-collection="'+escapeHtml(collection.id)+'">ver destinos desta coleção →</button></article>';}).join('');}
  function catalogRenderResults(){const list=$('catalogList');if(!list)return;catalogState.filtered=catalogState.items.filter(catalogMatches);const sort=$('catalogSort')?.value||'relevance';const sorted=[...catalogState.filtered].sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'pt-BR'):sort==='type'?a.type.localeCompare(b.type):sort==='saved'?Number(catalogState.favorites.has(b.id))-Number(catalogState.favorites.has(a.id)):0);catalogState.filtered=sorted;const meta=$('catalogMeta');if(meta)meta.textContent=catalogState.loading?'carregando catálogo…':catalogState.error?'catálogo indisponível':sorted.length+' destino(s) · '+catalogState.items.length+' registros locais · filtros no navegador';list.innerHTML=catalogState.loading?'<div class="catalog-empty">Carregando destinos, parcelas e experiências…</div>':catalogState.error?'<div class="catalog-empty"><strong>Não foi possível carregar o catálogo.</strong><br>'+escapeHtml(catalogState.error)+'<br><button type="button" class="button secondary" id="catalogRetry">tentar novamente</button></div>':sorted.length?sorted.map(catalogCard).join(''):'<div class="catalog-empty"><strong>Nenhum destino corresponde aos filtros.</strong><br>Tente remover um filtro ou limpar a busca.</div>';catalogRenderLocalStats();catalogRenderCollections();}
  function catalogSetMode(mode){catalogState.mode=mode;const isCollections=mode==='collections';$('catalogDestinationsPane').hidden=isCollections;$('catalogCollectionsPane').hidden=!isCollections;document.querySelectorAll('[data-catalog-mode]').forEach((button)=>button.classList.toggle('active',button.dataset.catalogMode===mode));if(isCollections)catalogRenderCollections();else catalogRenderResults();}
  function catalogOpenDetail(item){if(!item)return;const panel=$('catalogDetail');if(!panel)return;const image=$('catalogDetailImage');if(image){image.src=item.image||'';image.alt='Prévia de '+item.name;image.style.display=item.image?'block':'none';}catalogSection.dataset.detailId=item.id;$('catalogDetailName').textContent=item.name;$('catalogDetailType').textContent=catalogTypeLabel(item.type)+' · '+(item.category||'sem categoria')+' · '+(item.maturity||'—');$('catalogDetailSummary').textContent=item.description||'Sem descrição publicada.';$('catalogDetailOwner').textContent=[item.owner?('proprietário: '+item.owner):'',item.group?('grupo: '+item.group):''].filter(Boolean).join(' · ')||'proprietário/grupo não publicado';$('catalogDetailTags').innerHTML=(item.tags||[]).map((tag)=>'<span class="catalog-tag">#'+escapeHtml(tag)+'</span>').join('');$('catalogDetailSource').textContent=item.source+' · '+(item.data_status==='example'?'exemplo local':'dados públicos importados');$('catalogDetailSlurl').href=item.slurl;$('catalogDetailAccess').textContent='maturidade '+item.maturity+' · '+catalogAccessLabel(item.access);$('catalogDetailEvents').textContent=(item.related_events||[]).length?item.related_events.map((event)=>event.title||'evento relacionado').join(' · '):'Nenhum evento relacionado no recorte atual.';panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'center'});history.replaceState(null,'','#destination/'+encodeURIComponent(item.id));}
  function catalogToggle(setName,id){const set=catalogState[setName];if(set.has(id))set.delete(id);else set.add(id);catalogPersist();catalogRenderResults();toast(setName==='favorites'?(set.has(id)?'Destino favoritado localmente':'Favorito removido'):(set.has(id)?'Destino marcado como visitado':'Marca de visita removida'));}
  function catalogAddToCollection(id){const collection=catalogState.collections.find((item)=>item.id===catalogState.activeCollection);if(!collection){toast('Crie ou selecione uma coleção primeiro');return;}if(!collection.itemIds.includes(id))collection.itemIds.push(id);catalogPersist();catalogRenderCollections();toast('Destino adicionado à coleção local');}
  function catalogCreateCollection(){const input=$('catalogCollectionName');const name=input?.value.trim();if(!name){toast('Digite um nome para a coleção');return;}const id='collection-'+Date.now();catalogState.collections.push({id,name,itemIds:[]});catalogState.activeCollection=id;input.value='';catalogPersist();catalogRenderCollections();catalogSetMode('collections');toast('Coleção criada somente neste navegador');}
